customCSS:
.t, .history { color: #8a8980; }
.join { color: #6f894e; }
.part, .quit { color: #8a8980; }
.kick, .error { color: #c84053; }
.notice { color: #77713f; }
.action { color: #624c83; }
.mode, .nick, .topic, .server { color: #597b75; }
.highlight { color: #545464; background-color: #dcd5ac; border-left: 3px solid #624c83; padding-left: 8px; }
.reply { color: #8a8980; border-left: 2px solid #4d699b; padding-left: 6px; }
.oper { color: #f2ecbc; background-color: #77713f; }
.reactions { color: #4d699b; background-color: #e7dba0; }
.card { background-color: #e7dba0; border-color: #8a8980; }
.card-title { color: #4d699b; }
.card-desc { color: #8a8980; }
.daychange { color: #8a8980; border-color: #e7dba0; }
